// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address caller, address newDAO) public {
        vm.assume(caller != address(0));
        vm.assume(newDAO != address(0));
        // avoid caller == DAO so we test the dropped unconfigured allowance branch
        vm.assume(caller != c.DAO());

        // ensure not configured
        // (default is false, but assert to be safe)
        assertTrue(!c.configured());

        vm.prank(caller);
        try c.setDAO(newDAO) {
            // call succeeded: on the reference (which allows unconfigured updates)
            // DAO must become newDAO
            assertTrue(c.DAO() == newDAO);
        } catch {
            // If the reference reverted, the buggy version must also revert;
            // but with unconfigured and caller != DAO, the mutant reverts while
            // the reference succeeds. The assertion above catches the difference.
            // Here we assert the reference never reverts, which is true when
            // caller != DAO and newDAO != 0.
            assertTrue(false);
        }
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
